import { Text, View } from '@tarojs/components';

import './vehicle-list.less';

type Vehicle = {
  id: string;
  name: string;
};

export function VehicleList({ vehicles }: { vehicles: Vehicle[] }) {
  return (
    <View className="vehicle-list">
      {vehicles.map((vehicle, index) => {
        const isLast = index === vehicles.length - 1;
        const itemClassName = isLast
          ? 'vehicle-list__item vehicle-list__item--last'
          : 'vehicle-list__item';
        return (
          <View className={itemClassName} key={vehicle.id}>
            <Text className="vehicle-list__name">{vehicle.name}</Text>
          </View>
        );
      })}
    </View>
  );
}

